package com.edunest.backend.modules.topic.service.impl;
import com.edunest.backend.common.exception.ResourceNotFoundException; import com.edunest.backend.common.util.PublicIdUtils; import com.edunest.backend.modules.topic.dto.TopicResponse; import com.edunest.backend.modules.topic.entity.Topic; import com.edunest.backend.modules.topic.repository.TopicRepository; import com.edunest.backend.modules.topic.service.TopicService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class TopicServiceImpl implements TopicService { private final TopicRepository r; @Override @Transactional(readOnly=true) public List<TopicResponse> getTopicsByUnitId(Long id){return r.findByUnitIdAndActiveTrueOrderByTopicNumberAsc(id).stream().map(this::map).toList();} @Override @Transactional(readOnly=true) public TopicResponse getTopicById(Long id){return r.findByIdAndActiveTrue(id).map(this::map).orElseThrow(()->new ResourceNotFoundException("Topic not found"));} private TopicResponse map(Topic t){return TopicResponse.builder().id(PublicIdUtils.topicId(t.getId())).topicNumber(t.getTopicNumber()).name(t.getName()).description(t.getDescription()).active(t.isActive()).unitId(PublicIdUtils.unitId(t.getUnit().getId())).unitNumber(t.getUnit().getUnitNumber()).subjectId(PublicIdUtils.subjectId(t.getUnit().getSubject().getId())).subjectName(t.getUnit().getSubject().getName()).build();} }